            new Quote { Id = "https://ar.wikiquote.org/wiki/فدوى_طوقان", Text = "مِلْءُ قلبي هواكَ ما عادَ في القلبِ مكانٌ لكي يُحبّكَ أكثرْ", Author = "فدوى طوقان" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/فدوى_طوقان", Text = "كفانى أموت على أرضها وأدفن فيها وتحت ثراها أذوب وأفنى وأبعث عشبا على أرضها وأبعث زهرة تعيث بها كف طفل نمته بلادى , كفانى أظل بحضن بلادى ترابا وعشبا وزهرة.", Author = "فدوى طوقان" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/فدوى_طوقان", Text = "هناك أشياء عزيزة ونفيسة نؤثر أن نبقيها كامنة في زاوية من أرواحنا، بعيدة عن العيون المتطفلة، فلابد من إبقاء الغلالة مسدلة على بعض جوانب هذه الروح صونا لها من الابتذال", Author = "فدوى طوقان" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/فدوى_طوقان", Text = "آه يا موت! ترى ما أنت؟ قاسٍ أم حنون؟ أبشوش أنت أم جهمٌ ؟ وفيٌّ أم خؤون ؟", Author = "فدوى طوقان" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/فدوى_طوقان", Text = "كم بائس، كم جائع، كم فقير يكدح لا يجني سوى بؤسه ومُترَفٍ يلهو بدنيا الفجور قد حصر الحياة في كأسه", Author = "فدوى طوقان" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/فدوى_طوقان", Text = "يا حسرتا ماذا دهى أهل الحمى .. فالعيش ذل، والمصير بوار", Author = "فدوى طوقان" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/فدوى_طوقان", Text = "رأيت قصائد قلبي التي لم أقلها تموت واحدة بعد أخرى , حزنتُ وقمت إليها ألملمها جثثًا ورفاتْ", Author = "فدوى طوقان" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/فدوى_طوقان", Text = "ولقد نبتسمُ أحياناً ، لكي نخدع الحُزن فلا نبكي", Author = "فدوى طوقان" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/فدوى_طوقان", Text = "ليس هناك ما ينقذنا من ملاحقة أحزاننا ويخرجنا من ذواتنا كالأطفال وعالمهم الخاص المسحور", Author = "فدوى طوقان" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/فدوى_طوقان", Text = "إن الكتب لا تكفي كمصدر لمعرفة الحياة وما في العلاقات البشرية من تعقيد وتصادم , علينا أن نحيا في الحياة ذاتها. فتجاربنا الخاصة تظل هي الينبوع الأصلي لتلك المعرفة", Author = "فدوى طوقان" },
